 function enterDoor(id){const d=HeistStreet.districts.find(x=>x.id===street.district),door=id?d.doors.find(x=>x[0]===id):updateDoor();if(!door)return;persist();if(['foundry','canal','roof'].includes(door[0])){street.district=door[0];street.x=180;street.target=null;refreshStreet();persist();return;}if(door[0].startsWith('annex-'))start(byId(door[0]),{mode:'ghost'});else if(door[0]==='daily')daily();else navigate(door[0]==='academy'?'learn':door[0]);}
