 function useFriend(sample,mode,extra={}){hero=sample;previewing=mode==='preview';owned=mode==='owned'?{sample,checkedAt:Date.now(),mode:'owned-local',...extra}:null;save.friend=mode==='guest'?null:{mode,owner:extra.owner||null,tokenId:sample.tokenId,familyId:sample.familyId,seed:sample.seed,generation:sample.generation||extra.generation||null,frames:sample.frames};if(mode==='guest')save.hero=sample.tokenId;persist();settings();}
