  $('ownRead').onclick=async()=>{const b=$('ownRead');b.disabled=true;say('Checking ownership and reading frames...');try{if(!wallet.account)await connectWallet();const v=await HeistIdentity.read(wallet.provider,$('ownedId').value);useFriend(v.sample,'owned',{owner:v.owner,generation:v.generation,block:v.block});$('modal').close();toast('Playing as your Friend #'+v.sample.tokenId+'.');}catch(e){say(e.message);}finally{b.disabled=false;}};
