 function showReplays(){show('replays');$('replaysPage').innerHTML='<div class="title-row"><div><p class="kicker">YOUR DEVICE / 30 MOST RECENT JOBS</p><h1>ROUTE ARCHIVE.</h1></div><p class="subtitle">Scrub each turn. Compare your movement to the camera and laser forecast. Shared solutions unlock after the round ends.</p></div><div class="replaylist">'+(save.records.length?save.records.map((r,i)=>'<article class="replayrow"><div><h3>'+escape(r.level.name)+'</h3><p>'+escape(r.status.toUpperCase()+' / '+r.actions.length+' TURNS / '+(r.practice?'PRACTICE':r.mode.toUpperCase()))+'</p></div><button data-watch="'+i+'">WATCH</button><button data-export="'+i+'">EXPORT</button></article>').join(''):'<p>No recorded jobs yet. Finish or fail an attempt to create a replay.</p>')+'</div>';$('replaysPage').querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>watch(save.records[+b.dataset.watch]));$('replaysPage').querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download('rare-heist-route.json',JSON.stringify(save.records[+b.dataset.export],null,2),'application/json'));}
 function watch(r,index=0){const heroId=String(r.heroId||'3412'),replayHero=RF_ART.find(x=>x.tokenId===heroId)||replayFriends.get(heroId)||RF_ART[1]||RF_ART[0];const l=C.normalize(r.level),q=E.replay(l,r.actions,r.mode);if(!q.state||q.error?.startsWith('Invalid'))return toast('Invalid replay.');start(l,{type:'replay',mode:r.mode});game.replayHero=replayHero;if(!RF_ART.some(x=>x.tokenId===heroId)&&!replayFriends.has(heroId)&&/^[1-9][0-9]{0,77}$/.test(heroId)){const g=game;HeistIdentity.preview(heroId).then(v=>{replayFriends.set(heroId,v.sample);if(game===g)game.replayHero=v.sample;}).catch(()=>{});}index=Math.max(0,Math.min(q.states.length-1,Math.floor(index)||0));replay={record:r,states:q.states,index,playing:false,at:0};game.state=q.states[index];$('gameActions').hidden=true;$('replayBar').hidden=false;$('replayPosition').max=q.states.length-1;$('replayPosition').value=index;clearCheckpoint();hud();}
